import sys
from math import lcm
from collections import deque
def main():
    data = sys.stdin.read().split()
    n = int(data[0]); m = int(data[1]); k = int(data[2])
    grid = data[3:3 + n]
    rotas = data[3 + n:3 + n + k]
    L = 1
    for w in rotas:
        L = lcm(L, len(w))
    # lit[cell][t mod L]
    total = n * m
    lit = [None] * total
    start = target = -1
    for i in range(n):
        row = grid[i]
        for j in range(m):
            c = row[j]
            idx = i * m + j
            if c == '#':
                continue
            if c == 'S':
                start = idx; lit[idx] = [True] * L
            elif c == 'T':
                target = idx; lit[idx] = [True] * L
            else:
                w = rotas[ord(c) - 97]
                lit[idx] = [w[t % len(w)] == '1' for t in range(L)]
    seen = bytearray(total * L)
    seen[start * L] = 1
    dq = deque([(start, 0, 0)])
    while dq:
        cell, r, t = dq.popleft()
        if cell == target:
            print(t); return
        nr = (r + 1) % L
        i, j = divmod(cell, m)
        nxt = [cell]
        if i > 0: nxt.append(cell - m)
        if i + 1 < n: nxt.append(cell + m)
        if j > 0: nxt.append(cell - 1)
        if j + 1 < m: nxt.append(cell + 1)
        for c2 in nxt:
            lc = lit[c2]
            if lc is None or not lc[nr]:
                continue
            key = c2 * L + nr
            if seen[key]:
                continue
            seen[key] = 1
            dq.append((c2, nr, t + 1))
    print(-1)
main()

