import sys
from math import lcm
def main():
    data = sys.stdin.read().split()
    n = int(data[0]); m = int(data[1]); k = int(data[2])
    grid = data[3:3 + n]
    rotas = data[3 + n:3 + n + k]
    period = 1
    for w in rotas:
        period = lcm(period, len(w))
    def is_lit(i, j, t):
        c = grid[i][j]
        if c == '#':
            return False
        if c == 'S' or c == 'T':
            return True
        w = rotas[ord(c) - ord('a')]
        return w[t % len(w)] == '1'
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            if grid[i][j] == 'T':
                target = (i, j)
    # cur = set of cells the Herald can be in at minute t
    cur = {start}
    t = 0
    seen_states = set()
    while True:
        if target in cur:
            print(t); return
        key = (frozenset(cur), t % period)
        if key in seen_states:
            print(-1); return
        seen_states.add(key)
        t += 1
        nxt = set()
        for (i, j) in cur:
            for (a, b) in ((i, j), (i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)):
                if 0 <= a < n and 0 <= b < m and is_lit(a, b, t):
                    nxt.add((a, b))
        cur = nxt
main()
